def cell_kind(cell):
    if cell.value is None:
        return 'empty'
    if cell.data_type == 'f' or (isinstance(cell.value, str) and str(cell.value).startswith('=')):
        return 'formula'
    return 'fixed'

def find_header_row(ws, max_scan=30):
    best_row, best_score = None, 0
    for r in range(1, min(max_scan, ws.max_row or 1) + 1):
        texts = []
        for c in range(1, min(ws.max_column or 1, 80) + 1):
            v = ws.cell(r, c).value
            if v is not None and str(v).strip():
                texts.append(str(v).strip())
        if len(texts) >= 5:
            score = len(texts)
            if score > best_score:
                best_score = score
                best_row = r
    return best_row

